// src/App.jsx
import React, { useState, useEffect } from "react";
import Header from "./components/layout/Header";
import SciChart3DComponent from "./components/dashboard/SciChart3DComponent";
import CalendarFilter from "./components/dashboard/CalendarFilter";
import { fetchAvailableDates, fetchJavelinDataByDate } from "./services/api";

// Re-integrated from the old Sidebar component
const StatCard = ({ label, value, unit }) => (
  <div className="bg-gray-50 rounded-xl p-4">
    <p className="text-sm text-gray-600 font-medium">{label}</p>
    <p className="text-2xl font-semibold text-gray-900">
      {value ?? '...'} <span className="text-base font-normal text-gray-500 ml-1">{unit}</span>
    </p>
  </div>
);

const metricOrder = [
  { key: 'range', label: 'Range', unit: 'm' },
  { key: 'timeOfFlight', label: 'Time of Flight', unit: 's' },
  { key: 'peakHeight', label: 'Peak Height', unit: 'm' },
  { key: 'timeToPeak', label: 'Time to Peak', unit: 's' },
  { key: 'releaseSpeed', label: 'Release Speed', unit: 'm/s' },
  { key: 'releaseAngle', label: 'Release Angle', unit: '°' },
  { key: 'releaseHeight', label: 'Release Height', unit: 'm' },
];


function App() {
  const [allAvailableDates, setAllAvailableDates] = useState([]);
  const [selectedThrows, setSelectedThrows] = useState({});
  const [comparisonData, setComparisonData] = useState([]);
  const [sidebarStats, setSidebarStats] = useState({});
  const [sidebarThrowDetails, setSidebarThrowDetails] = useState(null);
  const [comparisonStats, setComparisonStats] = useState([]);
  const [loading, setLoading] = useState(false);
  const [visibility, setVisibility] = useState({});

  // Load available dates
  useEffect(() => {
    const getDates = async () => {
      try {
        const dates = await fetchAvailableDates();
        setAllAvailableDates(dates);
      } catch (error) {
        console.error("Failed to fetch dates:", error);
      }
    };
    getDates();
  }, []);

  // Load data for selected throws
  useEffect(() => {
    const datesToFetch = Object.keys(selectedThrows);
    const totalSelectedCount = Object.values(selectedThrows).reduce(
      (acc, throwsArr) => acc + throwsArr.length,
      0
    );

    if (totalSelectedCount === 0) {
      setComparisonData([]);
      setSidebarStats({});
      setSidebarThrowDetails(null);
      setComparisonStats([]);
      setVisibility({});
      return;
    }

    const getDataForComparison = async () => {
      setLoading(true);
      try {
        const dateDataPromises = datesToFetch.map((date) => fetchJavelinDataByDate(date));
        const fetchedDateResults = await Promise.all(dateDataPromises);
        const dateDataMap = new Map(datesToFetch.map((date, i) => [date, fetchedDateResults[i]]));
        const newChartData = [];
        const newComparisonStats = [];

        for (const date in selectedThrows) {
          const selectedIndices = selectedThrows[date];
          const dateData = dateDataMap.get(date);
          if (dateData?.throws) {
            selectedIndices.forEach((throwIndex) => {
              const throwData = dateData.throws[throwIndex];
              if (throwData) {
                const throwId = `${date} - Throw ${throwIndex + 1}`;
                newChartData.push({ id: throwId, trajectory: throwData.trajectory });
                newComparisonStats.push({
                  id: throwId,
                  date,
                  throwNum: throwIndex + 1,
                  time: throwData.time,
                  playerStats: throwData.playerStats,
                });
              }
            });
          }
        }

        setComparisonData(newChartData);
        setComparisonStats(newComparisonStats);
        setVisibility((prev) => {
          const merged = {};
          newComparisonStats.forEach((stat) => {
            merged[stat.id] = prev.hasOwnProperty(stat.id) ? prev[stat.id] : true;
          });
          return merged;
        });

        if (totalSelectedCount === 1) {
          const singleThrow = newComparisonStats[0];
          setSidebarStats(singleThrow.playerStats);
          setSidebarThrowDetails({
            date: singleThrow.date,
            throwNum: singleThrow.throwNum,
            time: singleThrow.time,
          });
        } else {
          setSidebarStats({});
          setSidebarThrowDetails(null);
        }
      } catch (error) {
        console.error("Failed to fetch comparison data:", error);
      } finally {
        setLoading(false);
      }
    };

    getDataForComparison();
  }, [selectedThrows]);

  const handleResetSelection = () => setSelectedThrows({});

  const totalSelectedCount = Object.values(selectedThrows).reduce(
    (acc, throwsArr) => acc + throwsArr.length,
    0
  );

  const renderMetrics = () => {
    const isComparisonView = totalSelectedCount > 1;

    if (isComparisonView) {
      const visibleStats = comparisonStats.filter(stat => visibility[stat.id]);
      return (
        <div className="p-6">
          <h2 className="text-xl font-bold text-gray-900 pb-4">Performance Comparison</h2>
          {visibleStats.length > 0 ? (
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b-2 border-gray-200">
                  <th className="py-2 pr-2 font-semibold text-gray-600 text-sm">Metric</th>
                  {visibleStats.map(throwData => (
                    <th key={throwData.id} className="py-2 px-2 text-center font-semibold text-gray-800">
                      <div className="text-sm">{`#${throwData.throwNum}`}</div>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {metricOrder.map(metric => (
                  <tr key={metric.key} className="border-b border-gray-100 last:border-b-0">
                    <td className="py-2 pr-2 font-semibold text-gray-600 text-sm">{metric.label}</td>
                    {visibleStats.map(throwData => (
                      <td key={throwData.id} className="py-2 px-2 text-center text-lg font-medium text-gray-900">
                        {throwData.playerStats[metric.key]}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <p className="text-gray-500 text-center mt-4">Enable visibility for a throw to see its data.</p>
          )}
        </div>
      );
    }

    return (
      <div className="p-6">
        {sidebarThrowDetails && (
          <div className="mb-6">
            <h3 className="text-lg font-bold text-gray-900">{sidebarThrowDetails.date}</h3>
            <p className="text-md text-gray-500">{`Throw ${sidebarThrowDetails.throwNum} (${sidebarThrowDetails.time})`}</p>
          </div>
        )}
        <h2 className="text-xl font-bold mb-4 text-gray-900">Performance Metrics</h2>
        <div className="space-y-3">
          {(loading && totalSelectedCount < 2)
            ? Array(7).fill(0).map((_, index) => <div key={index} className="bg-gray-100 rounded-xl p-4 h-20 animate-pulse"></div>)
            : metricOrder.map(metric => (
                <StatCard key={metric.key} label={metric.label} value={sidebarStats[metric.key]} unit={metric.unit} />
              ))}
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 text-gray-800">
      <Header />
      <div className="flex flex-1 overflow-hidden">
        {/* Left Sidebar */}
        <aside className="w-[380px] flex-shrink-0 bg-white border-r border-gray-200 flex flex-col">
          <div className="p-6 border-b border-gray-200">
            <CalendarFilter
              availableDates={allAvailableDates}
              selectedThrows={selectedThrows}
              onChange={setSelectedThrows}
              onReset={handleResetSelection}
            />
          </div>
          <div className="flex-1 overflow-y-auto">
            {totalSelectedCount > 0 ? renderMetrics() : (
              <div className="p-6 text-center text-gray-500">
                <h2 className="text-xl font-bold mb-4 text-gray-900">Performance Metrics</h2>
                <p>Select a throw to view its performance details.</p>
              </div>
            )}
          </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 p-8 overflow-y-auto">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Javelin Throw Analytics</h1>
          <p className="text-gray-500 mb-6">Select one or more throws from the calendar to begin comparison.</p>
          <SciChart3DComponent
            comparisonData={comparisonData}
            loading={loading}
            visibility={visibility}
            setVisibility={setVisibility}
          />
        </main>
      </div>
    </div>
  );
}

export default App;
